interface RobotsCacheEntry {
  value: string;
  expiresAt: number;
}

/**
 * In-memory TTL cache mapping host -> raw robots.txt body.
 * A stored value of "" is a legitimate cached result (empty robots.txt = allow all),
 * distinct from "no entry at all" (a genuine cache miss).
 */
class TtlCache<T> {
  private readonly store = new Map<string, RobotsCacheEntry>();

  async get(host: string): Promise<T | null> {
    const entry = this.store.get(host);
    if (!entry) {
      return null;
    }
    if (Date.now() > entry.expiresAt) {
      this.store.delete(host);
      return null;
    }
    return entry.value as unknown as T;
  }

  async set(host: string, value: T, ttlSeconds: number): Promise<void> {
    this.store.set(host, {
      value: value as unknown as string,
      expiresAt: Date.now() + ttlSeconds * 1000,
    });
  }
}

export const robotsCache = new TtlCache<string>();
export const TTL_SECONDS = 3600;

interface RobotsRules {
  disallow: string[];
  allow: string[];
}

export function parseRobots(body: string): RobotsRules {
  const disallow: string[] = [];
  const allow: string[] = [];

  for (const rawLine of body.split("\n")) {
    const line = rawLine.trim();
    if (line.toLowerCase().startsWith("disallow:")) {
      disallow.push(line.slice("disallow:".length).trim());
    } else if (line.toLowerCase().startsWith("allow:")) {
      allow.push(line.slice("allow:".length).trim());
    }
  }

  return { disallow, allow };
}

async function fetchRobotsBody(host: string): Promise<string> {
  const res = await fetch(`http://${host}/robots.txt`);
  // res.text can legitimately be "" for hosts that ship an empty robots.txt.
  return res.text();
}

/**
 * Used by every crawl worker before touching a URL on `host`.
 * Should hit the TTL cache on every call within the TTL window,
 * only re-fetching robots.txt once the cached entry expires.
 */
export async function getRobotsRules(host: string): Promise<RobotsRules> {
  const cached = await robotsCache.get(host);

  if (cached) {
    // Cache hit: parse the cached body without re-fetching.
    return parseRobots(cached);
  }

  // Cache miss: fetch fresh, cache it, then parse.
  const body = await fetchRobotsBody(host);
  await robotsCache.set(host, body, TTL_SECONDS);
  return parseRobots(body);
}
